    'Content-Type': 'application/json'
  },
  body: { p_limit: 10 },
  json: true
});

return { json: response };

// Format the weekly digest as a Slack message
const d = $input.item.json;
const total = d.total_entries_this_week || 0;
const crosslinked = d.total_crosslinked || 0;
const entries = d.top_entries || [];
const start = d.period_start ? new Date(d.period_start).toLocaleDateString('es-ES', {weekday:'long', day:'numeric', month:'long'}) : '?';
const end = d.period_end ? new Date(d.period_end).toLocaleDateString('es-ES', {weekday:'long', day:'numeric', month:'long'}) : '?';

if (total === 0) {
  return {
    json: {
      message: `:spiral_calendar_pad: *Digest Semanal NEYEN*\n_${start} — ${end}_\n\nSin nuevas entradas esta semana. La espiral descansa.`,
      has_entries: false
    }
  };
}

// Build entry list
const lines = entries.map((e, i) => {
  const medal = i === 0 ? ':first_place_medal:' : i === 1 ? ':second_place_medal:' : i === 2 ? ':third_place_medal:' : `${i + 1}.`;
  const tags = (e.tags || []).slice(0, 4).map(t => `\`${t}\``).join(' ');
  const summary = (e.summary || '').substring(0, 120);
  return `${medal} *${e.crosslink_count} links* — \`${e.file_name}\`\n    _${summary}${summary.length >= 120 ? '...' : ''}_\n    ${tags}`;
}).join('\n\n');

const msg = `:spiral_calendar_pad: *Digest Semanal NEYEN*\n_${start} — ${end}_\n\n` +
  `:bar_chart: *${total}* entradas | *${crosslinked}* con crosslinks\n\n` +
  `*Top entradas por conexiones:*\n\n${lines}\n\n` +
  `_La espiral sigue tejiendo conexiones._`;

return {
  json: {
    message: msg,
    has_entries: true,
    total: total,
    crosslinked: crosslinked
  }
};

// Post to Slack #general-neyen-core via incoming webhook
const msg = $input.item.json.message;

const slackResp = await this.helpers.httpRequest({
  method: 'POST',
  url: '{{ SLACK_WEBHOOK_PLACEHOLDER }}',
  headers: { 'Content-Type': 'application/json' },
  body: { text: msg },
  json: true,
  returnFullResponse: false
});

return {
  json: {
    status: 'ok',
    slack_response: slackResp,
    total: $input.item.json.total || 0,
    crosslinked: $input.item.json.crosslinked || 0
  }
};
